select case when s.rating >= 3.8 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end as rating_bucket, count(*) as product_count, sum(case when p.category = 'Fashion' then p.stock_qty else 0 end) as fashion_stock_qty from products p join suppliers s on p.supplier_id = s.id group by case when s.rating >= 3.8 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end having count(*) >= 2 order by product_count desc, rating_bucket;
